module ParamMulMixed(
  input  [7:0]  io_a,
                io_b,
  input         io_aSigned,
                io_bSigned,
  output [15:0] io_product
);

  assign io_product =
    {{8{io_aSigned & io_a[7]}}, io_a} * {{8{io_bSigned & io_b[7]}}, io_b};
endmodule

module ParamMulMixed_1(
  input  [7:0]  io_a,
  input  [3:0]  io_b,
  input         io_aSigned,
                io_bSigned,
  output [11:0] io_product
);

  assign io_product =
    {{4{io_aSigned & io_a[7]}}, io_a} * {{8{io_bSigned & io_b[3]}}, io_b};
endmodule

