module ShiftRightJam(
  input  [25:0] io_in,
  input  [7:0]  io_shamt,
  output [25:0] io_out,
  output        io_sticky
);

  wire        exceed_max_shift = io_shamt > 8'h1A;
  wire [31:0] _sticky_mask_T = 32'h1 << io_shamt[4:0];
  assign io_out = exceed_max_shift ? 26'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[25:0] - 26'h1 | {26{exceed_max_shift}}));
endmodule

module FarPath(
  input         io_in_a_sign,
  input  [7:0]  io_in_a_exp,
  input  [23:0] io_in_a_sig,
                io_in_b_sig,
  input  [7:0]  io_in_expDiff,
  input         io_in_effSub,
  output        io_out_result_sign,
  output [23:0] io_out_sig_a,
  output [27:0] io_out_sig_b,
  output [7:0]  io_out_exp_a_vec_0,
                io_out_exp_a_vec_1,
                io_out_exp_a_vec_2
);

  wire [25:0] _shiftRightJam_io_out;
  wire        _shiftRightJam_io_sticky;
  ShiftRightJam shiftRightJam (
    .io_in     ({io_in_b_sig, 2'h0}),
    .io_shamt  (io_in_expDiff),
    .io_out    (_shiftRightJam_io_out),
    .io_sticky (_shiftRightJam_io_sticky)
  );
  assign io_out_result_sign = io_in_a_sign;
  assign io_out_sig_a = io_in_a_sig;
  assign io_out_sig_b =
    (io_in_effSub
       ? {1'h1, ~_shiftRightJam_io_out, ~_shiftRightJam_io_sticky}
       : {1'h0, _shiftRightJam_io_out, _shiftRightJam_io_sticky}) + {27'h0, io_in_effSub};
  assign io_out_exp_a_vec_0 = io_in_a_exp + 8'h1;
  assign io_out_exp_a_vec_1 = io_in_a_exp;
  assign io_out_exp_a_vec_2 = io_in_a_exp - 8'h1;
endmodule

module LZA(
  input  [24:0] io_a,
                io_b,
  output [24:0] io_f
);

  assign io_f =
    {io_a[24] ^ io_b[24] ^ ~(~(io_a[23]) & ~(io_b[23])),
     io_a[23] ^ io_b[23] ^ ~(~(io_a[22]) & ~(io_b[22])),
     io_a[22] ^ io_b[22] ^ ~(~(io_a[21]) & ~(io_b[21])),
     io_a[21] ^ io_b[21] ^ ~(~(io_a[20]) & ~(io_b[20])),
     io_a[20] ^ io_b[20] ^ ~(~(io_a[19]) & ~(io_b[19])),
     io_a[19] ^ io_b[19] ^ ~(~(io_a[18]) & ~(io_b[18])),
     io_a[18] ^ io_b[18] ^ ~(~(io_a[17]) & ~(io_b[17])),
     io_a[17] ^ io_b[17] ^ ~(~(io_a[16]) & ~(io_b[16])),
     io_a[16] ^ io_b[16] ^ ~(~(io_a[15]) & ~(io_b[15])),
     io_a[15] ^ io_b[15] ^ ~(~(io_a[14]) & ~(io_b[14])),
     io_a[14] ^ io_b[14] ^ ~(~(io_a[13]) & ~(io_b[13])),
     io_a[13] ^ io_b[13] ^ ~(~(io_a[12]) & ~(io_b[12])),
     io_a[12] ^ io_b[12] ^ ~(~(io_a[11]) & ~(io_b[11])),
     io_a[11] ^ io_b[11] ^ ~(~(io_a[10]) & ~(io_b[10])),
     io_a[10] ^ io_b[10] ^ ~(~(io_a[9]) & ~(io_b[9])),
     io_a[9] ^ io_b[9] ^ ~(~(io_a[8]) & ~(io_b[8])),
     io_a[8] ^ io_b[8] ^ ~(~(io_a[7]) & ~(io_b[7])),
     io_a[7] ^ io_b[7] ^ ~(~(io_a[6]) & ~(io_b[6])),
     io_a[6] ^ io_b[6] ^ ~(~(io_a[5]) & ~(io_b[5])),
     io_a[5] ^ io_b[5] ^ ~(~(io_a[4]) & ~(io_b[4])),
     io_a[4] ^ io_b[4] ^ ~(~(io_a[3]) & ~(io_b[3])),
     io_a[3] ^ io_b[3] ^ ~(~(io_a[2]) & ~(io_b[2])),
     io_a[2] ^ io_b[2] ^ ~(~(io_a[1]) & ~(io_b[1])),
     io_a[1] ^ io_b[1] ^ ~(~(io_a[0]) & ~(io_b[0])),
     1'h0};
endmodule

module CLZ(
  input  [24:0] io_in,
  output [4:0]  io_out
);

  assign io_out =
    io_in[24]
      ? 5'h0
      : io_in[23]
          ? 5'h1
          : io_in[22]
              ? 5'h2
              : io_in[21]
                  ? 5'h3
                  : io_in[20]
                      ? 5'h4
                      : io_in[19]
                          ? 5'h5
                          : io_in[18]
                              ? 5'h6
                              : io_in[17]
                                  ? 5'h7
                                  : io_in[16]
                                      ? 5'h8
                                      : io_in[15]
                                          ? 5'h9
                                          : io_in[14]
                                              ? 5'hA
                                              : io_in[13]
                                                  ? 5'hB
                                                  : io_in[12]
                                                      ? 5'hC
                                                      : io_in[11]
                                                          ? 5'hD
                                                          : io_in[10]
                                                              ? 5'hE
                                                              : io_in[9]
                                                                  ? 5'hF
                                                                  : io_in[8]
                                                                      ? 5'h10
                                                                      : io_in[7]
                                                                          ? 5'h11
                                                                          : io_in[6]
                                                                              ? 5'h12
                                                                              : io_in[5]
                                                                                  ? 5'h13
                                                                                  : io_in[4]
                                                                                      ? 5'h14
                                                                                      : io_in[3]
                                                                                          ? 5'h15
                                                                                          : io_in[2]
                                                                                              ? 5'h16
                                                                                              : io_in[1]
                                                                                                  ? 5'h17
                                                                                                  : 5'h18;
endmodule

module NearPath(
  input         io_in_a_sign,
  input  [7:0]  io_in_a_exp,
  input  [23:0] io_in_a_sig,
  input         io_in_b_sign,
  input  [23:0] io_in_b_sig,
  input         io_in_need_shift_b,
  output        io_out_result_sign,
  output [7:0]  io_out_result_exp,
  output        io_out_sig_is_zero,
                io_out_a_lt_b,
                io_out_lza_error,
                io_out_int_bit,
  output [24:0] io_out_sig_raw,
  output [4:0]  io_out_lzc
);

  wire [24:0] _lza_ab_io_f;
  wire [24:0] b_sig = {io_in_b_sig, 1'h0} >> io_in_need_shift_b;
  wire [25:0] _a_minus_b_T_4 = {1'h0, io_in_a_sig, 1'h0} + {1'h1, ~b_sig} + 26'h1;
  wire        lza_str_zero = _lza_ab_io_f == 25'h0;
  wire        need_shift_lim = io_in_a_exp < 8'h19;
  wire [25:0] _shift_lim_mask_raw_T_2 = 26'h2000000 >> io_in_a_exp[4:0];
  wire [24:0] lzc_str =
    (need_shift_lim ? _shift_lim_mask_raw_T_2[24:0] : 25'h0) | _lza_ab_io_f;
  wire        _int_bit_mask_T_5 = lzc_str[23] & ~(lzc_str[24]);
  wire        _int_bit_mask_T_10 = lzc_str[22] & lzc_str[24:23] == 2'h0;
  wire        _int_bit_mask_T_15 = lzc_str[21] & lzc_str[24:22] == 3'h0;
  wire        _int_bit_mask_T_20 = lzc_str[20] & lzc_str[24:21] == 4'h0;
  wire        _int_bit_mask_T_25 = lzc_str[19] & lzc_str[24:20] == 5'h0;
  wire        _int_bit_mask_T_30 = lzc_str[18] & lzc_str[24:19] == 6'h0;
  wire        _int_bit_mask_T_35 = lzc_str[17] & lzc_str[24:18] == 7'h0;
  wire        _int_bit_mask_T_40 = lzc_str[16] & lzc_str[24:17] == 8'h0;
  wire        _int_bit_mask_T_45 = lzc_str[15] & lzc_str[24:16] == 9'h0;
  wire        _int_bit_mask_T_50 = lzc_str[14] & lzc_str[24:15] == 10'h0;
  wire        _int_bit_mask_T_55 = lzc_str[13] & lzc_str[24:14] == 11'h0;
  wire        _int_bit_mask_T_60 = lzc_str[12] & lzc_str[24:13] == 12'h0;
  wire        _int_bit_mask_T_65 = lzc_str[11] & lzc_str[24:12] == 13'h0;
  wire        _int_bit_mask_T_70 = lzc_str[10] & lzc_str[24:11] == 14'h0;
  wire        _int_bit_mask_T_75 = lzc_str[9] & lzc_str[24:10] == 15'h0;
  wire        _int_bit_mask_T_80 = lzc_str[8] & lzc_str[24:9] == 16'h0;
  wire        _int_bit_mask_T_85 = lzc_str[7] & lzc_str[24:8] == 17'h0;
  wire        _int_bit_mask_T_90 = lzc_str[6] & lzc_str[24:7] == 18'h0;
  wire        _int_bit_mask_T_95 = lzc_str[5] & lzc_str[24:6] == 19'h0;
  wire        _int_bit_mask_T_100 = lzc_str[4] & lzc_str[24:5] == 20'h0;
  wire        _int_bit_mask_T_105 = lzc_str[3] & lzc_str[24:4] == 21'h0;
  wire        _int_bit_mask_T_110 = lzc_str[2] & lzc_str[24:3] == 22'h0;
  wire        _int_bit_mask_T_115 = lzc_str[1] & lzc_str[24:2] == 23'h0;
  wire [24:0] _int_bit_predicted_T_1 =
    {lzc_str[24],
     _int_bit_mask_T_5,
     _int_bit_mask_T_10,
     _int_bit_mask_T_15,
     _int_bit_mask_T_20,
     _int_bit_mask_T_25,
     _int_bit_mask_T_30,
     _int_bit_mask_T_35,
     _int_bit_mask_T_40,
     _int_bit_mask_T_45,
     _int_bit_mask_T_50,
     _int_bit_mask_T_55,
     _int_bit_mask_T_60,
     _int_bit_mask_T_65,
     _int_bit_mask_T_70,
     _int_bit_mask_T_75,
     _int_bit_mask_T_80,
     _int_bit_mask_T_85,
     _int_bit_mask_T_90,
     _int_bit_mask_T_95,
     _int_bit_mask_T_100,
     _int_bit_mask_T_105,
     _int_bit_mask_T_110,
     _int_bit_mask_T_115,
     lzc_str[0] & lzc_str[24:1] == 24'h0 | lza_str_zero} & _a_minus_b_T_4[24:0];
  wire        exceed_lim =
    need_shift_lim
    & ({_lza_ab_io_f[24],
        |(_lza_ab_io_f[24:23]),
        |(_lza_ab_io_f[24:22]),
        |(_lza_ab_io_f[24:21]),
        |(_lza_ab_io_f[24:20]),
        |(_lza_ab_io_f[24:19]),
        |(_lza_ab_io_f[24:18]),
        |(_lza_ab_io_f[24:17]),
        |(_lza_ab_io_f[24:16]),
        |(_lza_ab_io_f[24:15]),
        |(_lza_ab_io_f[24:14]),
        |(_lza_ab_io_f[24:13]),
        |(_lza_ab_io_f[24:12]),
        |(_lza_ab_io_f[24:11]),
        |(_lza_ab_io_f[24:10]),
        |(_lza_ab_io_f[24:9]),
        |(_lza_ab_io_f[24:8]),
        |(_lza_ab_io_f[24:7]),
        |(_lza_ab_io_f[24:6]),
        |(_lza_ab_io_f[24:5]),
        |(_lza_ab_io_f[24:4]),
        |(_lza_ab_io_f[24:3]),
        |(_lza_ab_io_f[24:2]),
        |(_lza_ab_io_f[24:1])} & _shift_lim_mask_raw_T_2[23:0]) == 24'h0;
  LZA lza_ab (
    .io_a ({io_in_a_sig, 1'h0}),
    .io_b (~b_sig),
    .io_f (_lza_ab_io_f)
  );
  CLZ lzc_clz (
    .io_in  (lzc_str),
    .io_out (io_out_lzc)
  );
  assign io_out_result_sign = _a_minus_b_T_4[25] ? io_in_b_sign : io_in_a_sign;
  assign io_out_result_exp = io_in_a_exp;
  assign io_out_sig_is_zero = lza_str_zero & ~(_a_minus_b_T_4[0]);
  assign io_out_a_lt_b = _a_minus_b_T_4[25];
  assign io_out_lza_error = ~(|_int_bit_predicted_T_1) & ~exceed_lim;
  assign io_out_int_bit =
    exceed_lim
      ? (|(_shift_lim_mask_raw_T_2[24:0] & _a_minus_b_T_4[24:0]))
      : (|(_a_minus_b_T_4[23:0]
           & {lzc_str[24],
              _int_bit_mask_T_5,
              _int_bit_mask_T_10,
              _int_bit_mask_T_15,
              _int_bit_mask_T_20,
              _int_bit_mask_T_25,
              _int_bit_mask_T_30,
              _int_bit_mask_T_35,
              _int_bit_mask_T_40,
              _int_bit_mask_T_45,
              _int_bit_mask_T_50,
              _int_bit_mask_T_55,
              _int_bit_mask_T_60,
              _int_bit_mask_T_65,
              _int_bit_mask_T_70,
              _int_bit_mask_T_75,
              _int_bit_mask_T_80,
              _int_bit_mask_T_85,
              _int_bit_mask_T_90,
              _int_bit_mask_T_95,
              _int_bit_mask_T_100,
              _int_bit_mask_T_105,
              _int_bit_mask_T_110,
              _int_bit_mask_T_115})) | (|_int_bit_predicted_T_1);
  assign io_out_sig_raw = _a_minus_b_T_4[24:0];
endmodule

module FCMA_ADD_s1(
  input  [31:0] io_a,
                io_b,
  input  [2:0]  io_rm,
  output [2:0]  io_out_rm,
  output        io_out_far_path_out_sign,
                io_out_near_path_out_sign,
  output [7:0]  io_out_near_path_out_exp,
  output        io_out_special_case_valid,
                io_out_special_case_bits_iv,
                io_out_special_case_bits_nan,
                io_out_special_case_bits_inf_sign,
                io_out_small_add,
                io_out_far_path_mul_of,
  output [23:0] io_out_far_sig_a,
  output [27:0] io_out_far_sig_b,
  output [7:0]  io_out_far_exp_a_vec_0,
                io_out_far_exp_a_vec_1,
                io_out_far_exp_a_vec_2,
  output        io_out_near_path_sig_is_zero,
                io_out_near_path_lza_error,
                io_out_near_path_int_bit,
  output [24:0] io_out_near_path_sig_raw,
  output [4:0]  io_out_near_path_lzc,
  output        io_out_sel_far_path
);

  wire        _near_path_mods_1_io_out_result_sign;
  wire [7:0]  _near_path_mods_1_io_out_result_exp;
  wire        _near_path_mods_1_io_out_sig_is_zero;
  wire        _near_path_mods_1_io_out_lza_error;
  wire        _near_path_mods_1_io_out_int_bit;
  wire [24:0] _near_path_mods_1_io_out_sig_raw;
  wire [4:0]  _near_path_mods_1_io_out_lzc;
  wire        _near_path_mods_0_io_out_result_sign;
  wire [7:0]  _near_path_mods_0_io_out_result_exp;
  wire        _near_path_mods_0_io_out_sig_is_zero;
  wire        _near_path_mods_0_io_out_a_lt_b;
  wire        _near_path_mods_0_io_out_lza_error;
  wire        _near_path_mods_0_io_out_int_bit;
  wire [24:0] _near_path_mods_0_io_out_sig_raw;
  wire [4:0]  _near_path_mods_0_io_out_lzc;
  wire        decode_a_isInf = (&(io_a[30:23])) & ~(|(io_a[22:0]));
  wire        decode_a_isNaN = (&(io_a[30:23])) & (|(io_a[22:0]));
  wire        decode_b_isInf = (&(io_b[30:23])) & ~(|(io_b[22:0]));
  wire        decode_b_isNaN = (&(io_b[30:23])) & (|(io_b[22:0]));
  wire        _GEN = io_a[23] | ~(|(io_a[30:23]));
  wire [7:0]  raw_a_exp = {io_a[30:24], _GEN};
  wire [23:0] raw_a_sig = {|(io_a[30:23]), io_a[22:0]};
  wire        _GEN_0 = io_b[23] | ~(|(io_b[30:23]));
  wire [7:0]  raw_b_exp = {io_b[30:24], _GEN_0};
  wire [23:0] raw_b_sig = {|(io_b[30:23]), io_b[22:0]};
  wire        eff_sub = io_a[31] ^ io_b[31];
  wire        special_path_hasNaN = decode_a_isNaN | decode_b_isNaN;
  wire        special_path_inf_iv = decode_a_isInf & decode_b_isInf & eff_sub;
  wire [8:0]  _exp_diff_a_b_T_2 = {1'h0, io_a[30:24], _GEN} - {1'h0, io_b[30:24], _GEN_0};
  wire [7:0]  _exp_diff_b_a_T_2 = {io_b[30:24], _GEN_0} - {io_a[30:24], _GEN};
  wire        near_path_exp_neq = {io_a[24], _GEN} != {io_b[24], _GEN_0};
  wire        _near_path_out_T_2 =
    _exp_diff_a_b_T_2[8] | ~near_path_exp_neq & _near_path_mods_0_io_out_a_lt_b;
  FarPath far_path_mods_0 (
    .io_in_a_sign       (_exp_diff_a_b_T_2[8] ? io_b[31] : io_a[31]),
    .io_in_a_exp        (_exp_diff_a_b_T_2[8] ? raw_b_exp : raw_a_exp),
    .io_in_a_sig        (_exp_diff_a_b_T_2[8] ? raw_b_sig : raw_a_sig),
    .io_in_b_sig        (_exp_diff_a_b_T_2[8] ? raw_a_sig : raw_b_sig),
    .io_in_expDiff
      (_exp_diff_a_b_T_2[8] ? _exp_diff_b_a_T_2 : _exp_diff_a_b_T_2[7:0]),
    .io_in_effSub       (eff_sub),
    .io_out_result_sign (io_out_far_path_out_sign),
    .io_out_sig_a       (io_out_far_sig_a),
    .io_out_sig_b       (io_out_far_sig_b),
    .io_out_exp_a_vec_0 (io_out_far_exp_a_vec_0),
    .io_out_exp_a_vec_1 (io_out_far_exp_a_vec_1),
    .io_out_exp_a_vec_2 (io_out_far_exp_a_vec_2)
  );
  NearPath near_path_mods_0 (
    .io_in_a_sign       (io_a[31]),
    .io_in_a_exp        (raw_a_exp),
    .io_in_a_sig        (raw_a_sig),
    .io_in_b_sign       (io_b[31]),
    .io_in_b_sig        (raw_b_sig),
    .io_in_need_shift_b (near_path_exp_neq),
    .io_out_result_sign (_near_path_mods_0_io_out_result_sign),
    .io_out_result_exp  (_near_path_mods_0_io_out_result_exp),
    .io_out_sig_is_zero (_near_path_mods_0_io_out_sig_is_zero),
    .io_out_a_lt_b      (_near_path_mods_0_io_out_a_lt_b),
    .io_out_lza_error   (_near_path_mods_0_io_out_lza_error),
    .io_out_int_bit     (_near_path_mods_0_io_out_int_bit),
    .io_out_sig_raw     (_near_path_mods_0_io_out_sig_raw),
    .io_out_lzc         (_near_path_mods_0_io_out_lzc)
  );
  NearPath near_path_mods_1 (
    .io_in_a_sign       (io_b[31]),
    .io_in_a_exp        (raw_b_exp),
    .io_in_a_sig        (raw_b_sig),
    .io_in_b_sign       (io_a[31]),
    .io_in_b_sig        (raw_a_sig),
    .io_in_need_shift_b (near_path_exp_neq),
    .io_out_result_sign (_near_path_mods_1_io_out_result_sign),
    .io_out_result_exp  (_near_path_mods_1_io_out_result_exp),
    .io_out_sig_is_zero (_near_path_mods_1_io_out_sig_is_zero),
    .io_out_a_lt_b      (/* unused */),
    .io_out_lza_error   (_near_path_mods_1_io_out_lza_error),
    .io_out_int_bit     (_near_path_mods_1_io_out_int_bit),
    .io_out_sig_raw     (_near_path_mods_1_io_out_sig_raw),
    .io_out_lzc         (_near_path_mods_1_io_out_lzc)
  );
  assign io_out_rm = io_rm;
  assign io_out_near_path_out_sign =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_result_sign
      : _near_path_mods_0_io_out_result_sign;
  assign io_out_near_path_out_exp =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_result_exp
      : _near_path_mods_0_io_out_result_exp;
  assign io_out_special_case_valid =
    special_path_hasNaN | decode_a_isInf | decode_b_isInf;
  assign io_out_special_case_bits_iv =
    decode_a_isNaN & ~(io_a[22]) | decode_b_isNaN & ~(io_b[22]) | special_path_inf_iv;
  assign io_out_special_case_bits_nan = special_path_hasNaN | special_path_inf_iv;
  assign io_out_special_case_bits_inf_sign = decode_a_isInf ? io_a[31] : io_b[31];
  assign io_out_small_add = ~(|(io_a[30:23])) & ~(|(io_b[30:23]));
  assign io_out_far_path_mul_of = (&(io_b[30:23])) & ~eff_sub;
  assign io_out_near_path_sig_is_zero =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_is_zero
      : _near_path_mods_0_io_out_sig_is_zero;
  assign io_out_near_path_lza_error =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_lza_error
      : _near_path_mods_0_io_out_lza_error;
  assign io_out_near_path_int_bit =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_int_bit
      : _near_path_mods_0_io_out_int_bit;
  assign io_out_near_path_sig_raw =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_raw
      : _near_path_mods_0_io_out_sig_raw;
  assign io_out_near_path_lzc =
    _near_path_out_T_2 ? _near_path_mods_1_io_out_lzc : _near_path_mods_0_io_out_lzc;
  assign io_out_sel_far_path =
    ~eff_sub
    | (|(_exp_diff_a_b_T_2[8] ? _exp_diff_b_a_T_2[7:1] : _exp_diff_a_b_T_2[7:1]));
endmodule

module FCMA_ADD_s2(
  input  [2:0]  io_in_rm,
  input         io_in_far_path_out_sign,
                io_in_near_path_out_sign,
  input  [7:0]  io_in_near_path_out_exp,
  input         io_in_special_case_valid,
                io_in_special_case_bits_iv,
                io_in_special_case_bits_nan,
                io_in_special_case_bits_inf_sign,
                io_in_small_add,
                io_in_far_path_mul_of,
  input  [23:0] io_in_far_sig_a,
  input  [27:0] io_in_far_sig_b,
  input  [7:0]  io_in_far_exp_a_vec_0,
                io_in_far_exp_a_vec_1,
                io_in_far_exp_a_vec_2,
  input         io_in_near_path_sig_is_zero,
                io_in_near_path_lza_error,
                io_in_near_path_int_bit,
  input  [24:0] io_in_near_path_sig_raw,
  input  [4:0]  io_in_near_path_lzc,
  input         io_in_sel_far_path,
  output [31:0] io_result,
  output [4:0]  io_fflags
);

  wire [7:0]  near_path_res_exp;
  wire [22:0] _near_path_rounder_io_out;
  wire        _near_path_rounder_io_inexact;
  wire        _near_path_rounder_io_cout;
  wire        _near_path_tininess_rounder_io_tininess;
  wire [22:0] _far_path_rounder_io_out;
  wire        _far_path_rounder_io_inexact;
  wire        _far_path_rounder_io_cout;
  wire        _far_path_tininess_rounder_io_tininess;
  wire [27:0] _adder_result_T = {1'h0, io_in_far_sig_a, 3'h0} + io_in_far_sig_b;
  wire        keep = _adder_result_T[27:26] == 2'h1;
  wire        cancellation = _adder_result_T[27:26] == 2'h0;
  wire [26:0] _far_path_res_sig_T_21 =
    (_adder_result_T[27] ? {_adder_result_T[27:2], |(_adder_result_T[1:0])} : 27'h0)
    | (keep | io_in_small_add ? _adder_result_T[26:0] : 27'h0)
    | (cancellation & ~io_in_small_add ? {_adder_result_T[25:0], 1'h0} : 27'h0);
  wire [7:0]  _far_path_res_exp_T_4 =
    (_adder_result_T[27] ? io_in_far_exp_a_vec_0 : 8'h0)
    | (keep ? io_in_far_exp_a_vec_1 : 8'h0)
    | (cancellation ? io_in_far_exp_a_vec_2 : 8'h0);
  wire        far_path_of =
    (&_far_path_res_exp_T_4) | _far_path_rounder_io_cout & _far_path_res_exp_T_4 == 8'hFE
    | io_in_far_path_mul_of;
  wire        far_path_ix = _far_path_rounder_io_inexact | far_path_of;
  wire        near_path_is_zero = near_path_res_exp == 8'h0 & io_in_near_path_sig_is_zero;
  assign near_path_res_exp =
    io_in_near_path_int_bit
      ? io_in_near_path_out_exp - {3'h0, io_in_near_path_lzc}
        - {7'h0, io_in_near_path_lza_error}
      : 8'h0;
  wire [55:0] _sig_s1_T = {31'h0, io_in_near_path_sig_raw} << io_in_near_path_lzc;
  wire [24:0] sig_s2 =
    io_in_near_path_lza_error ? {_sig_s1_T[23:0], 1'h0} : _sig_s1_T[24:0];
  wire [7:0]  _near_path_exp_rounded_T =
    {7'h0, _near_path_rounder_io_cout} + near_path_res_exp;
  wire        near_path_zero_sign = io_in_rm == 3'h2;
  wire        near_path_ix = _near_path_rounder_io_inexact | (&_near_path_exp_rounded_T);
  wire        common_overflow =
    io_in_sel_far_path & far_path_of | ~io_in_sel_far_path & (&_near_path_exp_rounded_T);
  wire        rmin =
    io_in_rm == 3'h1 | near_path_zero_sign & ~io_in_far_path_out_sign | io_in_rm == 3'h3
    & io_in_far_path_out_sign;
  TininessRounder far_path_tininess_rounder (
    .io_in_sign  (io_in_far_path_out_sign),
    .io_in_sig   (_far_path_res_sig_T_21),
    .io_rm       (io_in_rm),
    .io_tininess (_far_path_tininess_rounder_io_tininess)
  );
  RoundingUnit far_path_rounder (
    .io_in       (_far_path_res_sig_T_21[25:3]),
    .io_roundIn  (_far_path_res_sig_T_21[2]),
    .io_stickyIn (|(_far_path_res_sig_T_21[1:0])),
    .io_signIn   (io_in_far_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_far_path_rounder_io_out),
    .io_inexact  (_far_path_rounder_io_inexact),
    .io_cout     (_far_path_rounder_io_cout)
  );
  TininessRounder near_path_tininess_rounder (
    .io_in_sign  (io_in_near_path_out_sign),
    .io_in_sig   ({sig_s2, 2'h0}),
    .io_rm       (io_in_rm),
    .io_tininess (_near_path_tininess_rounder_io_tininess)
  );
  RoundingUnit near_path_rounder (
    .io_in       (sig_s2[23:1]),
    .io_roundIn  (sig_s2[0]),
    .io_stickyIn (1'h0),
    .io_signIn   (io_in_near_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_near_path_rounder_io_out),
    .io_inexact  (_near_path_rounder_io_inexact),
    .io_cout     (_near_path_rounder_io_cout)
  );
  assign io_result =
    io_in_special_case_valid
      ? (io_in_special_case_bits_nan
           ? 32'h7FC00000
           : {io_in_special_case_bits_inf_sign, 31'h7F800000})
      : common_overflow
          ? {io_in_sel_far_path ? io_in_far_path_out_sign : io_in_near_path_out_sign,
             7'h7F,
             ~rmin,
             {23{rmin}}}
          : io_in_sel_far_path
              ? {io_in_far_path_out_sign,
                 {7'h0, _far_path_rounder_io_cout} + _far_path_res_exp_T_4,
                 _far_path_rounder_io_out}
              : {io_in_near_path_out_sign & ~near_path_is_zero | near_path_zero_sign
                   & near_path_is_zero,
                 _near_path_exp_rounded_T,
                 _near_path_rounder_io_out};
  assign io_fflags =
    io_in_special_case_valid
      ? {io_in_special_case_bits_iv, 4'h0}
      : {2'h0,
         common_overflow,
         io_in_sel_far_path & io_in_small_add & _far_path_tininess_rounder_io_tininess
           & ~io_in_far_path_mul_of & far_path_ix | ~io_in_sel_far_path
           & _near_path_tininess_rounder_io_tininess & near_path_ix,
         io_in_sel_far_path & far_path_ix | ~io_in_sel_far_path & near_path_ix};
endmodule

module AccumulatorInner(
