      s1Pipe_rBits_result <=
        s0Pipe_rBits_isInt ? s0Pipe_rBits_intResult : _addS2_io_result;
      s1Pipe_rBits_fflags <=
        s0Pipe_rBits_isInt ? s0Pipe_rBits_intFlags : _addS2_io_fflags;
      s1Pipe_rBits_tcCtrl_dataType <= s0Pipe_rBits_tcCtrl_dataType;
      s1Pipe_rBits_tcCtrl_dataTypeB <= s0Pipe_rBits_tcCtrl_dataTypeB;
      s1Pipe_rBits_tcCtrl_mixPrecision <= s0Pipe_rBits_tcCtrl_mixPrecision;
      s1Pipe_rBits_tcCtrl_Sparisity <= s0Pipe_rBits_tcCtrl_Sparisity;
      s1Pipe_rBits_tcCtrl_DAddress <= s0Pipe_rBits_tcCtrl_DAddress;
      s1Pipe_rBits_tcCtrl_clear <= s0Pipe_rBits_tcCtrl_clear;
      s1Pipe_rBits_tcCtrl_M <= s0Pipe_rBits_tcCtrl_M;
      s1Pipe_rBits_tcCtrl_N <= s0Pipe_rBits_tcCtrl_N;
      s1Pipe_rBits_tcCtrl_K <= s0Pipe_rBits_tcCtrl_K;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_m_mix <= s0Pipe_rBits_tcCtrl_OutputD_Idx_m_mix;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_n_mix <= s0Pipe_rBits_tcCtrl_OutputD_Idx_n_mix;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_m_f32 <= s0Pipe_rBits_tcCtrl_OutputD_Idx_m_f32;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_n_f32 <= s0Pipe_rBits_tcCtrl_OutputD_Idx_n_f32;
    end
  end // always @(posedge)
  FCMA_ADD_s1 addS1 (
    .io_a                              (io_in_bits_a),
    .io_b                              (io_in_bits_b),
    .io_rm                             (io_in_bits_rm),
    .io_out_rm                         (_addS1_io_out_rm),
    .io_out_far_path_out_sign          (_addS1_io_out_far_path_out_sign),
    .io_out_near_path_out_sign         (_addS1_io_out_near_path_out_sign),
    .io_out_near_path_out_exp          (_addS1_io_out_near_path_out_exp),
    .io_out_special_case_valid         (_addS1_io_out_special_case_valid),
